// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Owned} from "../src/Owned.sol";

contract InvMutTest is Test {
    Owned c;
    address admin;

    function setUp() public { c = new Owned(); admin = address(this); }

    function testFuzz_property(address newOwner) public {
        bool ok;
        bytes memory payload = abi.encodeWithSignature("setOwner(address)", newOwner);

        (bool success, bytes memory ret) = address(c).call(payload);
        if (success) {
            bool returned = false;
            if (ret.length >= 32) {
                returned = abi.decode(ret, (bool));
            }
            assertTrue(returned);
        } else {
            assertTrue(false);
        }
    }
}
